// The watch list: the generated data (`garmin.json`), the hand-kept part (`extra.ts`), the index the
// matcher searches, and helpers for the full list of supported models („Wszystkie obsługiwane
// zegarki — 118 modeli”). Pure, no DOM. Loaded only with the lazy watch check — the Garmin card in
// the main bundle reads `remember.ts` instead.
import { EXTRA, NICKNAMES, type ExtraItem } from './extra';
import json from './garmin.json';
import type { GarminData, SdkUnsupported, Supported, Target, Verdict } from './types';
import { isNoise, tokenize } from './words';

/** Generated by `npm run garmin:watches` from `garmin/manifest.xml` and the Connect IQ SDK device files. */
export const GARMIN = json as GarminData;

/** A supported product by its id (the remembered model, „Połącz zegarek”). */
export const supportedById = (id: string): Supported | undefined => GARMIN.supported.find((s) => s.id === id);

/** Lines in the order people look for them; any other line follows, alphabetically. */
const LINE_ORDER = [
  'Forerunner',
  'Venu',
  'vívoactive',
  'fēnix',
  'epix',
  'Instinct',
  'Enduro',
  'MARQ',
  'Descent',
  'Approach',
  'D2',
  'Legacy',
];

const byName = (a: string, b: string): number => a.localeCompare(b, 'pl', { numeric: true, sensitivity: 'base' });

export interface ListLine {
  series: string;
  /** Each supported product once, by its main name. */
  models: { id: string; name: string }[];
}

/** Every supported product, grouped by line. */
export function supportedByLine(): ListLine[] {
  const lines = new Map<string, ListLine['models']>();
  for (const s of GARMIN.supported) {
    lines.set(s.series, [...(lines.get(s.series) ?? []), { id: s.id, name: s.names[0]! }]);
  }
  const rank = (series: string) => {
    const i = LINE_ORDER.indexOf(series);
    return i < 0 ? LINE_ORDER.length : i;
  };
  return [...lines]
    .sort(([a], [b]) => rank(a) - rank(b) || byName(a, b))
    .map(([series, models]) => ({ series, models: models.sort((a, b) => byName(a.name, b.name)) }));
}

/* ---------------- the index ---------------- */

const supportedVerdict = (s: Supported): Verdict =>
  s.newest?.length
    ? { kind: 'update', newest: s.newest, lacks: s.lacks ?? [] }
    : s.lacks?.length
      ? { kind: 'limited', lacks: s.lacks }
      : { kind: 'full' };

const unsupportedVerdict = (u: SdkUnsupported): Verdict =>
  u.reason === 'notWatch'
    ? { kind: 'notWatch', what: u.kind! }
    : u.reason === 'notListed'
      ? { kind: 'noCiq' }
      : { kind: u.reason, ciq: u.ciq! };

const extraVerdict = (x: ExtraItem): Verdict => {
  switch (x.reason) {
    case 'noCiq':
      return { kind: 'noCiq' };
    case 'notWatch':
      return { kind: 'notWatch', what: x.kind as 'band' | 'scale' | 'bike' };
    case 'notYet':
      return { kind: 'notYet' };
    case 'regional':
      return { kind: 'regional', of: x.of! };
    case 'otherBrand':
      return { kind: 'otherBrand', ...(x.app ? { app: x.app } : {}), ...(x.only ? { only: x.only } : {}), bike: x.kind === 'bike' };
  }
};

/** One searchable name of a target. */
export interface Entry {
  name: string;
  /** Shown instead of `name` when the name is only a spelling („epix 2” → „epix™ (Gen 2)”). */
  shown: string;
  words: string[];
  /** Words that tell something (noise left out): a longer name ranks a little lower. */
  size: number;
  target: Target;
  /** Only the Asian version carries this name („Instinct 2 Dual Power”). */
  apac: boolean;
  /** Stands for a whole line: model words after it don't disqualify („Galaxy Watch 7”). */
  open: boolean;
  /** An official or curated name (shown as the title); a store spelling is shown only when it is what the person typed. */
  official: boolean;
}

const targets: Target[] = [];
const entries: Entry[] = [];
const apacTwin = new Set<string>();

/** Everything the check can answer about, in index order: supported, their Asian versions, unsupported, extras. */
export const TARGETS: readonly Target[] = targets;
/** Every name of every target. */
export const ENTRIES: readonly Entry[] = entries;
/** Supported products whose Asian version has names of its own. */
export const APAC_TWIN: ReadonlySet<string> = apacTwin;

const add = (
  t: Target,
  names: string[],
  o: { apac?: boolean; open?: (n: string) => boolean; shown?: (n: string) => string; official?: boolean } = {},
) => {
  for (const name of names) {
    const words = tokenize(name).words;
    entries.push({
      name,
      shown: o.shown?.(name) ?? name,
      words,
      size: words.filter((w) => !isNoise(w)).length,
      target: t,
      apac: o.apac ?? false,
      open: o.open?.(name) ?? false,
      official: o.official ?? true,
    });
  }
};

for (const s of GARMIN.supported) {
  const t: Target = { key: s.id, id: s.id, series: s.series, names: s.names, verdict: supportedVerdict(s) };
  targets.push(t);
  add(t, [...(NICKNAMES[s.id] ?? []), ...s.names]);
  add(t, s.aliases ?? [], { official: false });
  // „epix 2”, „MARQ 2 Aviator”: how people say Gen 2. Shown as the official name.
  for (const n of s.names.filter((x) => x.includes('(Gen 2)'))) add(t, [n.replace('(Gen 2)', '2')], { shown: () => n });
  if (s.apac?.names?.length) {
    apacTwin.add(s.id);
    const a: Target = { key: `${s.id}:apac`, id: s.id, series: s.series, names: s.apac.names, verdict: { kind: 'apac', lacks: s.apac.lacks } };
    targets.push(a);
    add(a, s.apac.names, { apac: true });
  }
}
const supportedKeys = new Set(entries.map((e) => e.words.join(' ')));
for (const u of GARMIN.unsupported) {
  const t: Target = { key: u.id, series: u.series, names: u.names, verdict: unsupportedVerdict(u) };
  targets.push(t);
  // A store alias that spells a supported name („vívoactive 3 Music” on the LTE model) is dropped: supported wins.
  const free = (n: string) => !supportedKeys.has(tokenize(n).words.join(' '));
  add(t, u.names.filter(free));
  add(t, (u.aliases ?? []).filter(free), { official: false });
}
for (const x of EXTRA) {
  const t: Target = { key: x.key, series: x.series ?? '', names: x.names, verdict: extraVerdict(x) };
  targets.push(t);
  add(t, x.names, { apac: x.reason === 'regional', open: (n) => x.open === true || (x.open ?? []).includes(n) });
}

/** Every word some name has — to take apart words typed without a space („7xpro”, „venusq”). */
export const VOCAB: ReadonlySet<string> = new Set(entries.flatMap((e) => e.words));

const byKey = new Map(targets.map((t) => [t.key, t]));

/** A target by its key: a supported id, `<id>:apac`, an unsupported SDK id or an extra's key. */
export const targetByKey = (key: string): Target | undefined => byKey.get(key);
